  FILTER(str(?z) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z02")
}

SELECT ?s ?p WHERE {
  ?s a brick:Zone .
  FILTER(str(?s) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z02")
